# Check: does a torch model with no params get affected by .to(dtype=bf16)?
import torch.nn as nn
class M(nn.Module):
    def forward(self, x, y):
        return torch.nn.functional.cross_entropy(x, y)
m = M()
print('Before:', [p.dtype for p in m.parameters()])
m = m.to(dtype=torch.bfloat16)
print('After:', [p.dtype for p in m.parameters()])
